<?php
namespace App\Http\Controllers;
use App\Support\HotelContext;
use App\Services\LedgerService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class FinanceController extends Controller {
    public function account(Request $r){$c=new HotelContext($r);$c->authorize('finance.manage');$d=$r->validate(['code'=>['required','regex:/^[0-9]{3,10}$/',\Illuminate\Validation\Rule::unique('ledger_accounts')->where('hotel_id',$c->hotel->id)],'name'=>'required|string|max:100','type'=>['required',Rule::in(['asset','liability','equity','income','expense'])]]);$id=DB::table('ledger_accounts')->insertGetId([...$d,'hotel_id'=>$c->hotel->id,'created_at'=>now(),'updated_at'=>now()]);$c->audit('Akun buku besar dibuat','ledger_accounts',$id);return response()->json(['message'=>'Akun buku besar disimpan.']);}
    public function report(Request $r){$c=new HotelContext($r);$c->authorize('finance.view');$d=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from']);$accounts=$c->table('ledger_accounts')->orderBy('code')->get();
        $entries=$c->table('journal_entries')->whereBetween('date',[$d['from'],$d['to']])->orderByDesc('date')->orderByDesc('id')->get();$lines=$c->table('journal_lines')->whereIn('journal_entry_id',$entries->pluck('id'))->get();$all=$c->table('journal_lines')->join('journal_entries','journal_entries.id','=','journal_lines.journal_entry_id')->where('journal_entries.date','<=',$d['to'])->select('account_id',DB::raw('SUM(debit) as debit'),DB::raw('SUM(credit) as credit'))->groupBy('account_id')->get()->keyBy('account_id');
        $accounts->each(function($a)use($lines,$all){$a->debit=(int)$lines->where('account_id',$a->id)->sum('debit');$a->credit=(int)$lines->where('account_id',$a->id)->sum('credit');$a->balance=(int)($all[$a->id]->debit??0)-(int)($all[$a->id]->credit??0);});
        return response()->json(['accounts'=>$accounts,'entries'=>$entries,'lines'=>$lines,'from'=>$d['from'],'to'=>$d['to'],'cash_basis'=>true])->header('Cache-Control','no-store');}
    public function rebuild(Request $r){$c=new HotelContext($r);$c->authorize('finance.manage');LedgerService::rebuild($c->hotel->id);$c->audit('Jurnal transaksi lama diselaraskan','hotels',$c->hotel->id);return response()->json(['message'=>'Jurnal transaksi diselaraskan tanpa menduplikasi pencatatan.']);}
    public function manual(Request $r){$c=new HotelContext($r);$c->authorize('finance.manage');$d=$r->validate(['date'=>'required|date_format:Y-m-d','description'=>'required|string|max:200','debit'=>['required','string',Rule::exists('ledger_accounts','code')->where('hotel_id',$c->hotel->id)],'credit'=>['required','string','different:debit',Rule::exists('ledger_accounts','code')->where('hotel_id',$c->hotel->id)],'amount'=>'required|integer|min:1|max:1000000000','request_key'=>'required|uuid']);LedgerService::post($c->hotel->id,'manual:'.$d['request_key'],$d['date'],$d['description'],[[$d['debit'],(int)$d['amount'],0],[$d['credit'],0,(int)$d['amount']]],auth()->id());$c->audit('Jurnal penyesuaian dibuat','hotels',$c->hotel->id);return response()->json(['message'=>'Jurnal penyesuaian seimbang disimpan.']);}
    public function refund(Request $r,int $id){$c=new HotelContext($r);$c->authorize('payments.manage');$d=$r->validate(['amount'=>'required|integer|min:1|max:1000000000','method'=>['required',Rule::in(['Tunai','Transfer','Kartu'])],'notes'=>'required|string|max:500','request_key'=>'required|uuid']);
        DB::transaction(function()use($c,$d,$id){$b=$c->table('reservations')->where('id',$id)->lockForUpdate()->first();abort_unless($b,404);if($c->table('payment_refunds')->where('request_key',$d['request_key'])->exists())return;$paid=$c->table('payments')->where('reservation_id',$id)->sum('amount')-$c->table('payment_refunds')->where('reservation_id',$id)->sum('amount');if($d['amount']>$paid)throw ValidationException::withMessages(['amount'=>'Refund melebihi pembayaran bersih reservasi.']);$entry=DB::table('payment_refunds')->insertGetId([...$d,'hotel_id'=>$c->hotel->id,'reservation_id'=>$id,'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);LedgerService::source('payment_refunds',$entry);$c->audit('Refund pembayaran dicatat','payment_refunds',$entry,['amount'=>$d['amount']]);});return response()->json(['message'=>'Refund dicatat. Pastikan pengembalian uang sudah dilakukan petugas.']);}
}
